const s = (v) => String(v == null ? '' : v).trim();
const low = (v) => s(v).toLowerCase();
const WIN_FROM = '2026-09-21', WIN_TO = '2026-09-25';
const inWin = (d) => { d = s(d); return /^\d{4}-\d{2}-\d{2}$/.test(d) && d >= WIN_FROM && d <= WIN_TO; };
const isYes = (x) => low(x) === 'yes';

// ---- PIPELINE ----
const rows = $('Read PIPELINE').all().map((i) => i.json).filter((r) => low(r.startup) === 'mindwox');
const sharedAll = [], weekShared = [], weekFu = [], passes = [], meetingRows = [], responses = [];
for (const r of rows) {
  const inv = s(r.investor);
  if (isYes(r.deal_shared)) sharedAll.push({ investor: inv, date: s(r.date_shared) });
  if (inWin(r.date_shared)) weekShared.push({ investor: inv, date: s(r.date_shared) });
  const fus = ['fu1_date', 'fu2_date', 'fu3_date'].filter((c) => inWin(r[c]));
  if (fus.length) weekFu.push({ investor: inv, count: fus.length });
  const resp = low(r.investor_response), ds = low(r.deal_status);
  if (['pass', 'passed', 'not relevant'].indexOf(resp) >= 0 || ['passed', 'not relevant'].indexOf(ds) >= 0) passes.push({ investor: inv, response: s(r.investor_response), pass_reason: s(r.pass_reason), last_contact: s(r.last_contact) });
  else if (s(r.investor_response)) responses.push({ investor: inv, response: s(r.investor_response), status: s(r.deal_status), last_contact: s(r.last_contact) });
  if (s(r.meeting_date) || isYes(r.meeting_scheduled) || ds.indexOf('meeting') >= 0 || s(r.last_meeting_date) || s(r.meetings_held)) meetingRows.push({ investor: inv, meeting_scheduled: s(r.meeting_scheduled), meeting_date: s(r.meeting_date), meetings_held: s(r.meetings_held), last_meeting_date: s(r.last_meeting_date), status: s(r.deal_status) });
}
const uniq = (a) => Array.from(new Set(a));

// ---- MAILBOXES ----
const boxes = [['Aditya investors@', 'Gmail Aditya'], ['Chaman dealflow@', 'Gmail Chaman'], ['Akansha', 'Gmail Akansha'], ['Shradhaa', 'Gmail Shradhaa']];
const mailStats = {}; const inbound = []; const outboundTo = {};
for (const [label, node] of boxes) {
  let items = [];
  try { items = $(node).all(); } catch (e) { continue; }
  let n = 0;
  for (const it of items) {
    const m = it.json || {};
    if (m.error || !m.id) continue;
    n++;
    const h = {};
    for (const k in (m.headers || {})) h[low(k)] = m.headers[k];
    const fromH = s(h.from), toH = s(h.to) + ' ' + s(h.cc), subj = s(h.subject), date = s(h.date);
    const fromSidana = /sidanaventures\.com/i.test(fromH);
    if (!fromSidana && !/mailer-daemon|calendly|fireflies|google\.com/i.test(fromH)) inbound.push({ mailbox: label, date, from: fromH.slice(0, 70), subject: subj.slice(0, 80) });
    if (fromSidana) { for (const a of (toH.match(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g) || [])) { const x = low(a); if (!/sidanaventures\.com|madrasmindworks/.test(x)) outboundTo[x] = (outboundTo[x] || 0) + 1; } }
  }
  mailStats[label] = n;
}
inbound.sort((a, b) => new Date(b.date) - new Date(a.date));

// ---- CALENDARS ----
const calNodes = ['Cal 1', 'Cal 2', 'Cal 3', 'Cal 4'];
const events = []; const calErrors = [];
for (const node of calNodes) {
  let items = [];
  try { items = $(node).all(); } catch (e) { calErrors.push(node + ': ' + e.message); continue; }
  for (const it of items) {
    const j = it.json || {};
    if (j.error) { calErrors.push(node + ': ' + JSON.stringify(j.error).slice(0, 120)); continue; }
    for (const ev of (j.items || [])) {
      events.push({ calendar: node, summary: s(ev.summary).slice(0, 90), start: s((ev.start || {}).dateTime || (ev.start || {}).date), attendees: (ev.attendees || []).map((a) => low(a.email)).filter((a) => !/sidanaventures\.com/.test(a)).slice(0, 6), status: s(ev.status) });
    }
  }
}
const evKey = {};
const calEvents = events.filter((e) => { const k = e.summary + '|' + e.start; if (evKey[k]) return false; evKey[k] = 1; return true; }).sort((a, b) => String(a.start).localeCompare(String(b.start)));

return [{ json: {
  startup: 'MindWox',
  week: WIN_FROM + ' .. ' + WIN_TO,
  pipeline: {
    rows: rows.length,
    total_investors_reached_till_date: uniq(sharedAll.map((x) => low(x.investor))).length,
    week_new_investors: weekShared.length, week_new_list: weekShared,
    week_followups: weekFu.reduce((a, b) => a + b.count, 0), week_followup_list: weekFu,
    passes_all_time: passes.length, passes,
    other_responses: responses,
    meeting_rows: meetingRows,
    first_share: sharedAll.map((x) => x.date).filter(Boolean).sort()[0] || '',
    last_share: sharedAll.map((x) => x.date).filter(Boolean).sort().pop() || ''
  },
  mailboxes: { messages_matching_mindwox: mailStats, inbound_from_outside: inbound.slice(0, 25), distinct_external_recipients_mailed: Object.keys(outboundTo).length, top_recipients: Object.entries(outboundTo).sort((a, b) => b[1] - a[1]).slice(0, 25) },
  calendars: { errors: calErrors, events_matching_mindwox: calEvents }
} }];
